import{_ as a,o as t,c as d,a0 as s}from"./chunks/framework.Bmhw_dvp.js";const u=JSON.parse('{"title":"架构总览","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/index.md","filePath":"advanced/index.md","lastUpdated":1791088295000}'),o={name:"advanced/index.md"};function n(i,e,c,r,l,p){return t(),d("div",null,[...e[0]||(e[0]=[s(`<h1 id="架构总览" tabindex="-1">架构总览 <a class="header-anchor" href="#架构总览" aria-label="Permalink to &quot;架构总览&quot;">​</a></h1><p>本页说明 ZViewer 的整体架构：进程与端口怎么划分、实时事件怎么注册、房间状态怎么分层存放，以及架构上做了哪些取舍。各子系统的实现细节，见本页末尾的「分区导航」一节。</p><h2 id="进程与端口" tabindex="-1">进程与端口 <a class="header-anchor" href="#进程与端口" aria-label="Permalink to &quot;进程与端口&quot;">​</a></h2><p>ZViewer 采用单进程架构，一个 Node.js 进程同时承担 API、前端静态资源和实时通信。浏览器、主后端与各内部服务之间的连接关系见第一个代码块。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>浏览器（React SPA）</span></span>
<span class="line"><span>   │  HTTP REST + Socket.IO WebSocket</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>后端（Express，端口 3333，统一入口）</span></span>
<span class="line"><span>   ├── REST 路由        /api/*        鉴权、房间、挂载、解析、音乐…</span></span>
<span class="line"><span>   ├── Socket.IO        /socket.io    房间实时同步（maxHttpBufferSize 20MB）</span></span>
<span class="line"><span>   ├── 静态托管          frontend/dist + SPA 回退</span></span>
<span class="line"><span>   ├── /live 反代       → Node Media Server（内部 3335）</span></span>
<span class="line"><span>   ├── /rtc 反代        → livekit-server（内部 3336，语音信令）</span></span>
<span class="line"><span>   └── 内嵌 NCM 服务     127.0.0.1:36530~36535（一起听音乐）</span></span>
<span class="line"><span>RTMP 3334 → Node Media Server → FLV 3335（仅容器/本机内部）</span></span>
<span class="line"><span>媒体 3333/udp → livekit-server（语音，详见拓展教程）</span></span></code></pre></div><p>四处端口的职责划分如下。</p><ul><li><strong>单进程单端口</strong>：生产模式所有流量走 3333（HTTP 与 HTTPS 二选一）。后端统一处理 API、前端静态资源、WebSocket、<code>/live</code> 与 <code>/rtc</code> 反代，因此没有跨域问题。</li><li><strong>RTMP 3334 独立端口</strong>：RTMP（Real-Time Messaging Protocol，推流用的 TCP 二进制协议）无法与 HTTP 复用端口，只能单独占用一个。拉流走内部 3335，由后端 <code>/live</code> 路径反代对外，Node Media Server 的端口无需暴露。</li><li><strong>内嵌 NCM 服务</strong>：一起听音乐依赖的网易云 API 服务，由主后端进程内嵌启动，绑定 <code>127.0.0.1</code>；端口被占用时端口号 +1 重试，最多 5 次。详见<a href="/advanced/music-pipeline">一起听音乐管线</a>。</li><li><strong>livekit-server 伴生进程</strong>：语音聊天的实时音频由独立的 LiveKit 服务承载，主后端只签发凭证与执行管理动作。媒体走 3333/udp，信令经 <code>/rtc</code> 反代。详见<a href="/advanced/voice">语音聊天链路</a>。</li></ul><h2 id="socket-io-事件注册模型" tabindex="-1">Socket.IO 事件注册模型 <a class="header-anchor" href="#socket-io-事件注册模型" aria-label="Permalink to &quot;Socket.IO 事件注册模型&quot;">​</a></h2><p>Socket.IO 是服务端与浏览器之间的双向实时通道，房间同步的绝大多数事件都经它传输。这一节说明事件在哪里注册，以及连接建立时如何鉴权。</p><p>后端所有实时事件经 <code>SocketRegistry</code>（<code>backend/src/modules/socket/event-handler.interface.ts</code>）统一注册。<code>io.on(&#39;connection&#39;)</code> 中依次调用 20 个事件 handler 的 <code>register(socket, io)</code>（<code>backend/src/index.ts</code>），每个 handler 只挂自己的事件名。ack（客户端发起请求时传入的回调函数，服务端用它回传执行结果）统一由 <code>safeAck</code> 包裹为 <code>{ success, message?, code?, data? }</code> 结构。要新增实时能力，实现该接口即可，无需改动连接入口。</p><p>连接鉴权在 <code>io.use</code> 中间件完成（<code>backend/src/index.ts</code>），JWT（JSON Web Token，登录后签发的身份令牌）的取用分两种情况：</p><ul><li><code>handshake.auth.agent === &#39;zcontrol-cli&#39;</code> 的连接直接放行，并标记 <code>isCliAgent</code>。CLI 代理的角色见 <a href="/advanced/cli-protocol">ZViewerCLI 代理协议</a>。</li><li>其余连接按 <strong>cookie 头 → <code>handshake.auth.token</code> → <code>handshake.query.token</code></strong> 的顺序取 JWT 校验，失败则拒绝握手。WebSocket 与 REST 共用同一套身份体系。</li></ul><h2 id="状态分层-内存权威副本-数据库节流落盘" tabindex="-1">状态分层：内存权威副本 + 数据库节流落盘 <a class="header-anchor" href="#状态分层-内存权威副本-数据库节流落盘" aria-label="Permalink to &quot;状态分层：内存权威副本 + 数据库节流落盘&quot;">​</a></h2><p>房间运行状态并不全部放在数据库里，而是分三层：内存里保留一份权威副本，数据库只做节流落盘。这样安排是为了让读操作永远命中内存，同时把写库次数压到最低。三层各自的载体与特点如下表。</p><table tabindex="0"><thead><tr><th>层</th><th>载体</th><th>特点</th></tr></thead><tbody><tr><td>运行时权威副本</td><td><code>RoomRuntimeState</code>（内存 Map，<code>room-state.service.ts</code>）</td><td>影片列表、当前影片、播放状态、字幕缓存；<strong>读永远走内存副本</strong></td></tr><tr><td>播放记忆</td><td><code>PlaybackMemoryService</code>（内存 + <code>PlaybackState</code> 表）</td><td>状态写入节流 2s、心跳落盘节流 10s，进程退出前 <code>flushAllDirty()</code> 最多丢 2s</td></tr><tr><td>持久化</td><td>Room / Movie / PlaybackState / MusicQueueItem 等表</td><td>后端重启后 <code>initFromDb()</code> 恢复</td></tr></tbody></table><p>这套分层能成立，靠的是一条贯穿全链路的推算公式（<code>PlaybackState</code> 实体注释）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>actualCurrentTime = currentTime + (Date.now() - lastUpdatedAt) / 1000 × playbackRate × (isPlaying ? 1 : 0)</span></span></code></pre></div><p>超过 duration 时收敛为 <code>currentTime = duration, isPlaying = false</code>。房主短暂断线时，服务器凭这条公式继续推算播放进度，观众端不中断；房主重连后从服务器取回状态，继续担任同步源。</p><h2 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to &quot;技术栈&quot;">​</a></h2><p>下表列出各层使用的技术。</p><table tabindex="0"><thead><tr><th>层</th><th>技术</th></tr></thead><tbody><tr><td>前端</td><td>React 18 + TypeScript + Vite + Tailwind CSS + Zustand</td></tr><tr><td>后端</td><td>Node.js + Express + TypeScript + Socket.IO</td></tr><tr><td>数据库</td><td>TypeORM + sql.js（wasm SQLite，无原生模块），可选 PostgreSQL</td></tr><tr><td>流媒体</td><td>Node Media Server（RTMP / HTTP-FLV）</td></tr><tr><td>音视频</td><td>浏览器端重封装 / 转码（playsvideo，随前端资源分发）</td></tr><tr><td>语音</td><td>LiveKit（livekit-server 伴生进程，WebRTC）</td></tr><tr><td>音乐</td><td>@neteasecloudmusicapienhanced/api（内嵌 HTTP 服务）</td></tr><tr><td>CLI</td><td>Go（独立仓库 ZViewerCLI）</td></tr></tbody></table><h2 id="贯穿全局的设计取舍" tabindex="-1">贯穿全局的设计取舍 <a class="header-anchor" href="#贯穿全局的设计取舍" aria-label="Permalink to &quot;贯穿全局的设计取舍&quot;">​</a></h2><p>以下几项取舍贯穿整个项目。它们不是某一处的局部实现，而是决定了很多具体做法为什么长成现在这样。</p><ul><li><strong>无原生模块</strong>：sql.js 是 wasm（WebAssembly，可以脱离原生编译环境运行的字节码）实现，单文件版在任意平台都能直接运行，不需要编译环境。服务器端 FFmpeg 已整体移除，音视频转码全部前置到浏览器。</li><li><strong>配置集中</strong>：数据库、证书、上传、推流切片、JWT 密钥文件全部放在 <code>config/</code> 目录；更新不覆盖，备份这一个目录即可。</li><li><strong>浏览器承担计算</strong>：字幕提取（MKV 流式 demux，即分离容器中的音视频与字幕轨道）、容器重封装、音轨转码都在浏览器端完成。服务器只做转发与解析，带宽和 CPU 压力集中在必要的流上。</li><li><strong>JWT 密钥自举</strong>：密钥按「环境变量 → <code>config/jwt-secrets.json</code> → 自动生成 64 位 hex 写回文件」三级回退获取（<code>middleware/auth.ts</code> <code>loadOrCreateSecret</code>），首次启动无需配置。</li><li><strong>代理统一出口</strong>：媒体代理、<code>/live</code> 反代、音频代理共用 <code>proxyHttpUpstream</code>（<code>services/proxy/http-proxy.ts</code>），统一处理 Range 有界分片、条件请求、断连销毁与流量日志。</li></ul><h2 id="分区导航" tabindex="-1">分区导航 <a class="header-anchor" href="#分区导航" aria-label="Permalink to &quot;分区导航&quot;">​</a></h2><p>以下页面按子系统展开各自的实现细节。</p><ul><li><a href="/advanced/sync">房间同步逻辑</a></li><li><a href="/advanced/voice">语音聊天链路</a></li><li><a href="/advanced/video-pipeline">视频源与 API 获取逻辑</a></li><li><a href="/advanced/music-pipeline">一起听音乐管线</a></li><li><a href="/advanced/cli-protocol">ZViewerCLI 代理协议</a></li><li><a href="/advanced/theme-system">主题系统实现</a></li><li><a href="/advanced/https">HTTPS 证书</a></li><li><a href="/advanced/auth">鉴权与权限模型</a></li><li><a href="/advanced/api">REST API 参考</a></li><li><a href="/advanced/env">环境变量</a></li><li><a href="/advanced/build-update">构建与更新机制</a></li></ul>`,27)])])}const v=a(o,[["render",n]]);export{u as __pageData,v as default};
